// anchoredWorkflowRegex builds a regex matching the complete workflow identity.
// If the value pins a ref (contains "@"), the ref must match exactly; otherwise
// an optional "@<ref>" suffix is permitted.
func anchoredWorkflowRegex(identity string) string {
	if strings.Contains(identity, "@") {
		return "^" + regexp.QuoteMeta(identity) + "$"
	}
	return "^" + regexp.QuoteMeta(identity) + "(@.+)?$"
}
